pub fn topo_all_7(vm: &mut WamState, a1: Value, a2: Value, a3: Value, a4: Value, a5: Value, a6: Value, a7: Value) -> bool {
    let (code, labels) = get_shared_wam();
    vm.code = code.clone();
    vm.labels = labels.clone();
    vm.pc = 2352;
    vm.set_reg("A1", a1);
    vm.set_reg("A2", a2);
    vm.set_reg("A3", a3);
    vm.set_reg("A4", a4);
    vm.set_reg("A5", a5);
    vm.set_reg("A6", a6);
    vm.set_reg("A7", a7);
    vm.run()
}

